import React, { Fragment, useEffect} from "react"
import axios from "axios"
import { trackPromise } from "react-promise-tracker"


const ShowSharePointFiles = props => {
  const {  currentRacf, sharePointID, setDisplayAlert, setRefreshSharePointList, refreshSharePointList, sharePointFiles, setSharePointFiles, year} = props

  useEffect(() => {    

      trackPromise(
        axios({
          url: "/spoint/api/getsharepointfiles",
          method: "POST",
          headers: {
            "Content-type": "application/json",
            api: "yes"
          },
          data: JSON.stringify({  racf :currentRacf,sharePointID:sharePointID, year:year })
        })
          .then(response => response.data)
          .then(response => {
            setSharePointFiles(response)
            //console.log('getSharePointFiles', response)
          })
          .catch(err => {
            if (err.response.status === 404) {
              setDisplayAlert({ message: "Folder on SharePoint was not created !", position: 4, timeout: 2000, color: "alert__red" })
            }
          }),
        "getSharePoint"
      )

   
  }, [setDisplayAlert, sharePointID, currentRacf, refreshSharePointList, setSharePointFiles, year])

 
  const downloadSharePointFile = (file_name, uid) => {
    trackPromise(
      fetch(`/spoint/api/downloadSharePointFile?uid=${encodeURIComponent(uid)}`, {
        method: "GET",
        headers: {
          "Cache-Control": "no-cache"
        }
      })
        .then(response => {
          if (!response.ok) {
            throw new Error("Download failed");
          }
          return response.blob();
        })
        .then(blob => {
          const url = window.URL.createObjectURL(new Blob([blob]));
          const link = document.createElement("a");
          link.href = url;
          link.setAttribute("download", file_name);

          document.body.appendChild(link);

          link.click();

          link.parentNode.removeChild(link);
          window.URL.revokeObjectURL(url);
        })
        .catch(error => {
          console.error("Error downloading file:", error);
        }),
      "downloadSharePoint"
    );
  }

  
  const handleDeleteSPfile = id => {
    var confirm = window.confirm("Are you sure you want to delete the SharePoint file ? ")
    if (confirm !== true) {
      return
    }
    trackPromise(
      axios({
        url: "/spoint/api/deleteSPfile",
        method: "POST",
        headers: {
          "Content-type": "application/json"
        },
        data: JSON.stringify({ _id: id })
      })            
      .then(response => {        
          setDisplayAlert({ message: "SharePoint file deleted successfully !", position: 4, timeout: 3000, color: "alert__green" })                   
          setRefreshSharePointList(x=>!x)              
          document.getElementById("sharePoint_file").value = null            
      })        
      .catch(err => {
          setDisplayAlert({ message: "Error deleting the SP file !", position: 4, timeout: 3000, color: "alert__red" })
      }),
      "deleteSharePoint"
    )
  }
 
  return (
    <Fragment>
      {sharePointFiles ? (
        <div className="showSharePointFiles_section">
          <div className="showSharePointFiles_grid_header">
            <div>File Name</div>
            <div>File Size</div>
            <div>Download</div>
            <div>File Type</div>
            <div>Delete</div>
          </div>

          <div>
            {sharePointFiles.length > 0
              ? (
                  sharePointFiles.map((line, index) =>
                    <div key={index} className="showSharePointFiles_grid_detail">
                      <div>{line.filename}</div>
                      <div>{line.size}</div>
                      <div>
                        <i
                          className="clickable fa fa-download"
                          onClick={() => {
                            downloadSharePointFile(line.filename, line.uid)
                          }}
                        ></i>
                      </div>
                      <div>
                        <i className="fa fa-file fa-file-doc"></i>
                      </div>       
                      {true? (
                        <div>
                          <button
                            id="sharePointFiles_deleteButton"
                            onClick={() => {
                              handleDeleteSPfile(line.uid)                              
                            }}
                          >
                            &times;
                          </button>
                        </div>
                      ) : (
                        <div>&nbsp;</div>
                      )}
                    </div>
                  )
                )
              : (  
                <div key={0} className="showSharePointFiles_grid_detail">
                        <div>No Files</div>
                        <div></div>          
                        <div></div>          
                        
                </div>)
            }       
          </div>
        </div>
      ) : null}
    </Fragment>
  )
}
export default ShowSharePointFiles
