import React, { Fragment, useState } from "react"
import axios from "axios"
import { trackPromise } from "react-promise-tracker"
 
const UploadForm = props => {
  const { setDisplayAlert, sharePointPath,  sharePointID, currentRacf, userProfile, setRefreshSharePointList, year} = props
  const [selectedFile, setSelectedFile] = useState()
  // const [uploadResult, setUploadResult] = useState([])
  
  const handleFile = event => {
    setSelectedFile({ file: event.target.files })
  }

  const showUploadAlert = (uploadResult) => {
    let msg = "" 
    for (let i = 0; i < uploadResult.length; i += 1) {
          msg = msg.concat('\n\n', uploadResult[i].file, ' - ',uploadResult[i].reason ) 
    }
    if (msg.length > 0) {
      msg = "Following files cannot be uploaded : ".concat(msg) 
      alert (msg)
    }
    else return
  }
 

  const handleUpload = async () => {

    const files = selectedFile.file      
    
    
    const options = {
      headers: {
        sharePointID : sharePointID,        
        'relative-url': sharePointPath.concat('/', currentRacf),
        name: userProfile.userName,
        office: userProfile.office,
      }
    }


    try {      
      
      let uploadResult = []
      const formData = new FormData();

      for (let i = 0; i < files.length; i++) {
        formData.append("files[]", files[i])
        try {
          await trackPromise(axios.post("/spoint/api/upload", formData, options), "uploadSharePoint")
          setDisplayAlert({ message: "Successfully uploaded " + files[i].name + " !!", position: 4, timeout: 10000, color: "alert__green" })
          //setUploadResult(prev=>prev.concat({ file: files[i].name, status: "Complete", reason:"N/A"}))           
        } catch (error) {    
          const errMessage = error.response.data.error_message
          setDisplayAlert({ message: errMessage, position: 4, timeout: 10000, color: "alert__red" })
          uploadResult = uploadResult.concat({ file: files[i].name, status: "Failed", reason:errMessage })          
        }
      }       
      setRefreshSharePointList(x=>!x)
      showUploadAlert(uploadResult)
      document.getElementById("sharePoint_file").value = null  
  
    } catch (err) {
      setDisplayAlert({ message: "Unexpected upload error !!", osition: 3, timeout: 10000, color: "alert__red" })     
      document.getElementById("sharePoint_file").value = null            
    }        
  }
 
  return (
    <Fragment>
      <div className="uploadDoc">
           <form>
            <input type="file" multiple name="file" id="sharePoint_file" onChange={handleFile} />
            <button type="button" onClick={handleUpload}>
              Upload Documents
            </button>
          </form>
       </div>
    </Fragment>
  )
}

export default UploadForm